create table if not exists public.themes (
  theme_key text primary key,
  owner_user_id integer references public.users(id) on delete cascade,
  source text not null check (source in ('builtin', 'imported', 'custom')),
  source_palette_id integer,
  name text not null,
  scheme text not null default 'dark' check (scheme in ('dark', 'light')),
  palette_colors jsonb not null,
  theme_colors jsonb not null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint themes_custom_owner_check check ((source = 'custom' and owner_user_id is not null) or (source <> 'custom' and owner_user_id is null)),
  constraint themes_palette_length_check check (jsonb_typeof(palette_colors) = 'array' and jsonb_array_length(palette_colors) = 10),
  constraint themes_color_shape_check check (jsonb_typeof(theme_colors) = 'object')
);

create table if not exists public.user_theme_menu_items (
  user_id integer not null references public.users(id) on delete cascade,
  theme_key text not null references public.themes(theme_key) on delete cascade,
  position integer not null check (position >= 0 and position < 8),
  created_at timestamptz not null default now(),
  primary key (user_id, theme_key),
  unique (user_id, position)
);

create index if not exists themes_owner_user_id_idx on public.themes(owner_user_id);
create index if not exists themes_source_idx on public.themes(source);
create index if not exists user_theme_menu_items_user_id_idx on public.user_theme_menu_items(user_id);

alter table public.themes enable row level security;
alter table public.user_theme_menu_items enable row level security;

drop policy if exists themes_select_available on public.themes;
create policy themes_select_available on public.themes
  for select
  to authenticated
  using (
    owner_user_id is null
    or exists (
      select 1 from public.users u
      where u.id = themes.owner_user_id
        and u.clerk_user_id = auth.uid()::text
    )
  );

drop policy if exists themes_insert_owned_custom on public.themes;
create policy themes_insert_owned_custom on public.themes
  for insert
  to authenticated
  with check (
    source = 'custom'
    and exists (
      select 1 from public.users u
      where u.id = themes.owner_user_id
        and u.clerk_user_id = auth.uid()::text
    )
  );

drop policy if exists themes_update_owned_custom on public.themes;
create policy themes_update_owned_custom on public.themes
  for update
  to authenticated
  using (
    source = 'custom'
    and exists (
      select 1 from public.users u
      where u.id = themes.owner_user_id
        and u.clerk_user_id = auth.uid()::text
    )
  )
  with check (
    source = 'custom'
    and exists (
      select 1 from public.users u
      where u.id = themes.owner_user_id
        and u.clerk_user_id = auth.uid()::text
    )
  );

drop policy if exists themes_delete_owned_custom on public.themes;
create policy themes_delete_owned_custom on public.themes
  for delete
  to authenticated
  using (
    source = 'custom'
    and exists (
      select 1 from public.users u
      where u.id = themes.owner_user_id
        and u.clerk_user_id = auth.uid()::text
    )
  );

drop policy if exists user_theme_menu_items_select_owned on public.user_theme_menu_items;
create policy user_theme_menu_items_select_owned on public.user_theme_menu_items
  for select
  to authenticated
  using (exists (select 1 from public.users u where u.id = user_theme_menu_items.user_id and u.clerk_user_id = auth.uid()::text));

drop policy if exists user_theme_menu_items_insert_owned on public.user_theme_menu_items;
create policy user_theme_menu_items_insert_owned on public.user_theme_menu_items
  for insert
  to authenticated
  with check (exists (select 1 from public.users u where u.id = user_theme_menu_items.user_id and u.clerk_user_id = auth.uid()::text));

drop policy if exists user_theme_menu_items_update_owned on public.user_theme_menu_items;
create policy user_theme_menu_items_update_owned on public.user_theme_menu_items
  for update
  to authenticated
  using (exists (select 1 from public.users u where u.id = user_theme_menu_items.user_id and u.clerk_user_id = auth.uid()::text))
  with check (exists (select 1 from public.users u where u.id = user_theme_menu_items.user_id and u.clerk_user_id = auth.uid()::text));

drop policy if exists user_theme_menu_items_delete_owned on public.user_theme_menu_items;
create policy user_theme_menu_items_delete_owned on public.user_theme_menu_items
  for delete
  to authenticated
  using (exists (select 1 from public.users u where u.id = user_theme_menu_items.user_id and u.clerk_user_id = auth.uid()::text));

on conflict (theme_key) do update set
  source = excluded.source,
  source_palette_id = excluded.source_palette_id,
  name = excluded.name,
  scheme = excluded.scheme,
  palette_colors = excluded.palette_colors,
  theme_colors = excluded.theme_colors,
  updated_at = now()
where public.themes.owner_user_id is null;
